<script setup lang="ts">
import { computed,ref } from 'vue'
import { traceInput } from '../../diagnostics/stability'
import { PhCrosshair,PhArrowCounterClockwise,PhPaperPlaneTilt,PhTerminalWindow } from '@phosphor-icons/vue'
import TaskHistoryPanel from './TaskHistoryPanel.vue'
import {statusLabel as archiveStatus} from '../../history/records'
import type {TaskHistoryController} from '../../composables/useTaskHistory'
import BusinessResultCard from './BusinessResultCard.vue'
import {TASK_TEMPLATES,type AgentTask,type Finding} from '../../agent/taskRunner'
import type { ActionRecord } from '../../agent/types'
const props=defineProps<{records:ActionRecord[];reply:string;selectedId:string|null;contextName:string;taskState:string;focusCommand?:string;plantMode?:boolean;focusCommands?:string[];mode?:'DEMO'|'LLM';gateway?:{ready:boolean;reason:string};task?:AgentTask;findings?:Finding[];scenarioId?:string;history:TaskHistoryController}>()
const emit=defineEmits<{send:[text:string];cancel:[];mode:[mode:'DEMO'|'LLM'];refreshGateway:[];trend:[evidenceId:string];rerun:[taskId:string]}>()
const command=ref(''),limit=ref(20),showTemplates=ref(true),tab=ref<'current'|'history'>('current')
const shortcuts=computed(()=>props.focusCommands??[props.focusCommand??'定位一号曝气池'])
const visibleRecords=computed(()=>props.records.slice(-limit.value).reverse())
const statusLabel=(s:string)=>({IDLE:'等待指令',PENDING:'等待执行',RUNNING:'正在执行',SUCCEEDED:'执行成功',PARTIAL:'部分完成',FAILED:'执行失败',CANCELLED:'已取消'} as Record<string,string>)[s]
function send(text=command.value) {if(!text.trim()||!props.history.owner.value)return;command.value='';showTemplates.value=false;emit('send',text.trim())}
const time=(v:string)=>new Date(v).toLocaleTimeString('zh-CN',{hour12:false})
</script>
<template>
  <aside class="agent-panel"><div class="agent-heading"><span class="agent-symbol"><PhCrosshair :size="24"/></span><div><h2>场景工作台</h2><p>{{mode==='LLM'?'LLM Agent · 实际工具循环':'Demo Agent · 确定性演示解析器'}}</p></div></div>
    <div class="agent-mode-row"><label>驱动模式 <select :value="mode??'DEMO'" @change="$emit('mode',($event.target as HTMLSelectElement).value as 'DEMO'|'LLM')"><option value="DEMO">Demo</option><option value="LLM" :disabled="!gateway?.ready">LLM（{{gateway?.ready?'已配置':'未配置'}}）</option></select></label><button class="text-button" @click="$emit('refreshGateway')">检查连接</button><small>{{gateway?.reason??'只读演示'}}</small><small>SIMULATED · 演示数据</small></div>
    <div class="agent-context"><span>当前设备上下文</span><strong>{{contextName}}</strong><code>{{selectedId?'三维选中：'+selectedId:'三维无选中对象'}}</code><div class="task-state" :data-status="taskState"><i class="status-dot"/>{{statusLabel(taskState)}}<button class="text-button cancel-task" :disabled="taskState!=='RUNNING'&&taskState!=='PENDING'" @click="event=>{traceInput('cancel_control_received',{trusted:event.isTrusted,eventTimestamp:event.timeStamp});emit('cancel')}">取消</button></div></div>
    <nav class="agent-tabs" aria-label="任务视图"><button :aria-pressed="tab==='current'" @click="tab='current'">当前任务</button><button :aria-pressed="tab==='history'" @click="tab='history';history.refresh()">历史任务</button></nav>
    <div class="agent-body"><TaskHistoryPanel v-if="tab==='history'" :history="history" @rerun="$emit('rerun',$event);tab='current'"/><div v-show="tab==='current'"><div v-if="task" class="current-save"><span :data-save-status="history.saveStates.value[task.task_id]?.status">{{archiveStatus(history.saveStates.value[task.task_id]?.status??'SAVING')}}</span><button class="text-button" @click="history.open(task.task_id)">查看记录 / 导出</button><small v-if="history.saveStates.value[task.task_id]?.status==='ERROR'">{{history.saveStates.value[task.task_id]?.message}}</small></div><div class="task-progress" v-if="task">步骤 {{task.tool_count}} / 20 · 模型请求 {{task.model_requests}} / 6</div><button class="text-button" @click="showTemplates=!showTemplates">{{showTemplates?'收起任务模板':'任务快捷入口'}}</button><div v-if="showTemplates" class="business-shortcuts"><button v-for="template in TASK_TEMPLATES" :key="template" @click="send(template)">{{template}}</button></div><details class="scene-shortcuts"><summary>场景快捷定位</summary><div class="command-suggestions"><button v-for="cmd in shortcuts" :key="cmd" @click="send(cmd)"><PhCrosshair :size="17"/>{{cmd}}</button><button @click="send('回到总览')"><PhArrowCounterClockwise :size="17"/>回到总览</button></div></details><BusinessResultCard v-if="task" :task="task" :findings="findings??[]" :scenario-id="scenarioId??''" @trend="$emit('trend',$event)"/><p class="reply" aria-live="polite">{{reply}}</p>
      <div class="execution-heading"><PhTerminalWindow :size="17"/><span>真实工具执行记录</span><span class="record-count">{{records.length}}</span></div><div v-if="!records.length" class="empty-record"><p>尚无工具调用</p><small>仅开放七个只读数据 / 受控展示工具</small></div><div v-else class="action-records"><article v-for="record in visibleRecords" :key="record.action_id" class="action-record" :data-status="record.status" :data-source="record.source"><div class="record-top"><span>{{statusLabel(record.status)}}</span><time>{{time(record.started_at)}}</time></div><p class="record-source">{{record.source==='USER'?'用户界面操作':record.source==='TEST'?'验收调用':record.source==='LLM'?'LLM 工具调用':'Demo Agent 任务'}} · {{record.trigger}}</p><strong>{{record.tool_name}}</strong><code v-if="record.arguments.device_id">{{record.arguments.device_id}}</code><small v-else>{{record.tool_name==='scene.reset_view'?'默认总览 · 清除选择':record.arguments.alarm_id??'固定任务快照范围'}}</small><p v-if="record.error">{{record.error.code}} · {{record.error.message}}</p><p v-else-if="record.status==='SUCCEEDED'">{{record.tool_name.startsWith('scene.')?'相机及实际渲染已确认':record.tool_name==='chart.show_trend'?'同快照图表提交已确认':'只读查询成功 · 依据已记录'}}</p><details><summary>执行详情</summary><pre>{{JSON.stringify(record,null,2)}}</pre></details></article><button v-if="records.length>limit" class="secondary-button" @click="limit+=20">加载更早记录（还有 {{records.length-limit}} 条）</button></div>
    </div></div><TaskHistoryPanel v-if="tab==='current'&&history.selected.value" :history="history" detail-only @rerun="$emit('rerun',$event)"/><form class="agent-input" @submit.prevent="send()"><label for="command">只读任务</label><div><input :disabled="!history.owner.value" id="command" v-model="command" placeholder="输入只读任务或定位指令…" autocomplete="off"/><button :disabled="!history.owner.value" aria-label="发送指令" type="submit"><PhPaperPlaneTilt :size="20" weight="fill"/></button></div><p v-if="history.owner.value">只读模拟数据与受控展示 · 不连接真实设备</p><p v-else>{{history.ownerMessage.value}} <button type="button" class="text-button" @click="history.claim()">申请执行权</button></p></form>
  </aside>
</template>
